#include <iostream>
#include <memory>
#include <vector>
#include <iomanip>

// Abstract Base Class
class Shape {
public:
    virtual ~Shape() = default; // Essential virtual destructor
    virtual double area() const = 0; // Pure virtual function
    virtual void print() const = 0;  // Pure virtual function
};

class Circle : public Shape {
private:
    double radius;
public:
    explicit Circle(double r) : radius(r) {}
    double area() const override { return 3.1415926535 * radius * radius; }
    void print() const override {
        std::cout << "Circle(radius=" << std::fixed << std::setprecision(2) << radius 
                  << ", area=" << area() << ")\n";
    }
};

class Rectangle : public Shape {
private:
    double width, height;
public:
    Rectangle(double w, double h) : width(w), height(h) {}
    double area() const override { return width * height; }
    void print() const override {
        std::cout << "Rectangle(w=" << std::fixed << std::setprecision(2) << width 
                  << ", h=" << height << ", area=" << area() << ")\n";
    }
};

int main() {
    // Polymorphic collection using C++11/17 smart pointers
    std::vector<std::unique_ptr<Shape>> shapes;
    shapes.push_back(std::make_unique<Circle>(3.0));
    shapes.push_back(std::make_unique<Rectangle>(4.0, 5.0));

    double totalArea = 0.0;
    for (const auto& s : shapes) {
        s->print(); // Dynamic dispatch via vtable
        totalArea += s->area();
    }

    std::cout << "Total Area: " << std::fixed << std::setprecision(2) << totalArea << "\n";
    return 0;
}

#include <iostream>
#include <memory>
#include <vector>
#include <typeinfo>

class Employee {
public:
    virtual ~Employee() = default;
    virtual double earnings() const = 0;
    virtual void print() const {
        std::cout << "Employee earnings: " << earnings();
    }
};

class CommissionEmployee : public Employee {
protected:
    double grossSales;
    double commissionRate;
public:
    CommissionEmployee(double sales, double rate) 
        : grossSales(sales), commissionRate(rate) {}
    double earnings() const override { return grossSales * commissionRate; }
};

class BasePlusCommissionEmployee : public CommissionEmployee {
private:
    double baseSalary;
public:
    BasePlusCommissionEmployee(double sales, double rate, double base)
        : CommissionEmployee(sales, rate), baseSalary(base) {}
    double earnings() const override { return baseSalary + CommissionEmployee::earnings(); }
    void setBaseSalary(double newBase) { baseSalary = newBase; }
    double getBaseSalary() const { return baseSalary; }
};

int main() {
    std::vector<std::unique_ptr<Employee>> staff;
    staff.push_back(std::make_unique<CommissionEmployee>(10000.0, 0.06));
    staff.push_back(std::make_unique<BasePlusCommissionEmployee>(5000.0, 0.04, 1200.0));

    for (const auto& emp : staff) {
        // Attempt safe downcast
        auto* basePlusPtr = dynamic_cast<BasePlusCommissionEmployee*>(emp.get());
        if (basePlusPtr != nullptr) {
            std::cout << "Found BasePlusCommissionEmployee. Current base: " 
                      << basePlusPtr->getBaseSalary() << "\n";
            basePlusPtr->setBaseSalary(basePlusPtr->getBaseSalary() * 1.10);
            std::cout << "Updated base salary (+10%): " 
                      << basePlusPtr->getBaseSalary() << "\n";
        } else {
            std::cout << "Standard employee processed.\n";
        }
        std::cout << "Final Earnings: " << emp->earnings() << "\n";
    }
    return 0;
}
